import{_ as t,o as i,c as e,ag as a}from"./chunks/framework.ePeAWSvT.js";const g=JSON.parse('{"title":"Looping Lists","description":"","frontmatter":{},"headers":[],"relativePath":"guide/looping-lists.md","filePath":"guide/looping-lists.md"}'),n={name:"guide/looping-lists.md"};function o(l,s,r,h,p,d){return i(),e("div",null,[...s[0]||(s[0]=[a(`<h1 id="looping-lists" tabindex="-1">Looping Lists <a class="header-anchor" href="#looping-lists" aria-label="Permalink to &quot;Looping Lists&quot;">​</a></h1><p>A <strong>Looping List</strong> is a map group that iterates a source and produces one child item per iteration. It is the mechanism behind every parent/child mapping in the platform — sales order lines, item prices, shipment packages, and so on.</p><p>For the mechanics of adding a Looping List to a route, and for filtering and delete handling, see <a href="./datahub-action-mapping.html">Action Mapping</a>.</p><div class="info custom-block"><p class="custom-block-title">What makes a map group a Looping List</p><p>A Looping List has exactly <strong>one inner map group</strong> (the shape of a single child) and <strong>no property maps of its own</strong>. Everything you map inside it describes one child; the loop repeats that shape once per item it produces.</p></div><h2 id="custom-lists" tabindex="-1">Custom Lists <a class="header-anchor" href="#custom-lists" aria-label="Permalink to &quot;Custom Lists&quot;">​</a></h2><p>A Looping List doesn&#39;t have to target a list the Data Model already declares. It can also populate a <strong>Custom List</strong> — a user-defined, free-form child collection you can attach to any entity to extend the common model with a relationship it doesn&#39;t already define. The looping methods below work the same either way; the only difference is whether the destination is a declared property or a Custom List you named.</p><p>For what a Custom List is, when to use one, how to set it up, and how its children behave and sync, see the dedicated <strong><a href="./custom-lists.html">Custom Lists</a></strong> guide.</p><h2 id="looping-methods-read-publish-side" tabindex="-1">Looping Methods (read / publish side) <a class="header-anchor" href="#looping-methods-read-publish-side" aria-label="Permalink to &quot;Looping Methods (read / publish side)&quot;">​</a></h2><p>When you configure a Looping List on a <strong>read</strong> action, a <strong>Looping Method</strong> picker appears beside the source selector. It controls <em>how</em> the loop turns the source into children. There are three methods:</p><table tabindex="0"><thead><tr><th>Method</th><th>In-app help</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Loop All</strong></td><td>&quot;Each matched item becomes a child.&quot;</td><td>The selector matches an <strong>array</strong> in the source; each matched element becomes one child.</td></tr><tr><td><strong>Group by Field</strong></td><td>&quot;Groups items by a field into sub-lists.&quot;</td><td>Takes a targeted list and groups its items by a target field. A nested Looping List can be embedded from each grouping to build sub-lists.</td></tr><tr><td><strong>Split by Separator</strong></td><td>&quot;Splits a value into one child each.&quot;</td><td>Takes a <strong>single delimited scalar</strong> and splits it on a separator, fanning out to one child per token.</td></tr></tbody></table><h3 id="loop-all" tabindex="-1">Loop All <a class="header-anchor" href="#loop-all" aria-label="Permalink to &quot;Loop All&quot;">​</a></h3><p>The connector selector (a JSONPath on JSON, XPath on XML) points at an <strong>array</strong> in the source. Each element of that array becomes exactly one child, and the inner map group maps each element&#39;s fields onto the child.</p><p><strong>Source:</strong></p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;contacts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;A&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;B&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>With a Looping List whose selector points at <code>contacts</code>, this produces <strong>two children</strong> — one for <code>A</code>, one for <code>B</code>. This is the everyday case: a repeating array in the payload becomes a list on the model.</p><h3 id="group-by-field" tabindex="-1">Group by Field <a class="header-anchor" href="#group-by-field" aria-label="Permalink to &quot;Group by Field&quot;">​</a></h3><p>Group by Field takes a targeted list and groups its items by the value of a target field (the <strong>Group By Property</strong>). Each distinct value becomes one grouping. You can then <strong>embed a nested Looping List</strong> from those groupings to build sub-lists — turning one flat list into a hierarchy.</p><p>Use it when the connector hands you a single flat collection but the model needs a hierarchy. For example, a <strong>flat list of shipment lines</strong> that needs to become <strong>Shipment → Packages → Package Contents</strong>:</p><table tabindex="0"><thead><tr><th>Flat shipment line</th><th>Package ID</th></tr></thead><tbody><tr><td>Line 1</td><td>PKG-1</td></tr><tr><td>Line 2</td><td>PKG-1</td></tr><tr><td>Line 3</td><td>PKG-2</td></tr></tbody></table><p>Grouping the rows <strong>by package id</strong> turns each distinct package into a grouping; a nested Looping List embedded from those groupings produces each package&#39;s <strong>contents</strong> sub-list — <code>PKG-1</code> becomes a Package whose contents are Line 1 and Line 2, and <code>PKG-2</code> becomes a Package whose contents are Line 3.</p><p>Because every line in a grouping shares the group&#39;s key, the <strong>intermediate item can also take its own properties from the grouped lines</strong> — each Package can map package-level fields (a tracking number, weight, carrier) off the lines it was grouped from. So a single Group by Field builds all three layers at once:</p><ol><li><strong>Shipment</strong> — the parent the Looping List sits on.</li><li><strong>Packages</strong> — the groupings (layer 2), each carrying package-level fields read from its grouped lines.</li><li><strong>Package Contents</strong> — the nested Looping List over the lines within each grouping (layer 3).</li></ol><h3 id="split-by-separator" tabindex="-1">Split by Separator <a class="header-anchor" href="#split-by-separator" aria-label="Permalink to &quot;Split by Separator&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Preview</p><p>Split by Separator is in <strong>Preview</strong> and is rolling out across environments. Your Central environment may not run it yet — availability may lag the configuration UI until the full release completes.</p></div><p>Split by Separator operates on a <strong>single delimited scalar value</strong> rather than an array. It splits that one value on a separator (e.g. <code>;</code>) and <strong>fans out to one child per token</strong>. Here, <strong>one source row = one parent</strong>, and the split column produces N children (projections) from it.</p><ul><li>Each split child&#39;s only intrinsic data is <strong>the token itself</strong> — typically mapped to the child&#39;s <strong>primary key</strong>.</li><li>Other child fields come from the parent via <strong>&quot;map from parent&quot;</strong> (the child pulls values off the parent record it was split from).</li><li><strong>Empty or blank tokens produce no child</strong> — they are skipped, so a trailing separator or a doubled delimiter does not create an empty item.</li></ul><p><strong>Source</strong> — a HubSpot-style contact with a delimited custom field:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;contact-1001&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;firstName&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Jordan&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;properties&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;property_certifications&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;CPA;PMP;CFA&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Configure a Looping List whose:</p><ul><li><strong>Central List</strong> = a Custom List named <code>Certifications</code></li><li><strong>Looping Method</strong> = Split by Separator, separator = <code>;</code></li><li><strong>Child sub-type</strong> = <code>Certification</code></li><li><strong>Child primary-key map</strong> = the split token</li></ul><p>The model then gets a <code>Certifications</code> Custom List with <strong>three <code>ChildCustomEntity</code> children</strong>, keyed by each token:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;contact-1001&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;firstName&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Jordan&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;customLists&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;Certifications&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;subType&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Certification&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;primaryKey&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;CPA&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;subType&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Certification&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;primaryKey&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PMP&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;subType&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Certification&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;primaryKey&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;CFA&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><em>(Illustrative shape — the exact envelope differs, but the important part is: one delimited value became three keyed children.)</em></p><div class="info custom-block"><p class="custom-block-title">Keys are scoped per parent</p><p>The same child key can exist under <strong>multiple parents independently</strong> — <code>CPA</code> under <code>contact-1001</code> is a distinct child from <code>CPA</code> under another contact. Each child also syncs downstream with its <strong>own</strong> create / update / delete lifecycle.</p></div><h2 id="save-subscribe-side" tabindex="-1">Save / Subscribe Side <a class="header-anchor" href="#save-subscribe-side" aria-label="Permalink to &quot;Save / Subscribe Side&quot;">​</a></h2><p>On a <strong>save</strong> action, a Looping List does the reverse: it <strong>emits the children back out</strong>, one output element per child. For a JSON connector that is an array named by the connector property; for XML a repeating element; for a file, one row per child (parent columns repeated).</p><p>Each emitted child carries its <strong>own operation</strong> — create, update, or delete — based on the child&#39;s key state. Which operations are actually written is governed by the Looping List&#39;s <strong>Supported Operations</strong>, and deletes are never assumed. See <a href="./datahub-action-mapping.html#filtering-looping-list-items-by-operation-deletes-_destroy">Filtering Looping List Items by Operation</a> in the Action Mapping guide for the full rules and the <code>_destroy</code> recipe.</p><div class="warning custom-block"><p class="custom-block-title">Custom-list children need a sub-typed child model</p><p>When a Looping List targets a Custom List, the <strong>child Data Model must have an Entity Sub Type</strong>. If it does not, the platform raises an error rather than emitting untyped children — so set the child model&#39;s sub type before saving the map.</p></div><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="./custom-lists.html">Custom Lists</a> — Attaching a user-defined child collection to any entity</li><li><a href="./datahub-action-mapping.html">Action Mapping</a> — Adding Looping Lists to a route, filters, and delete handling</li><li><a href="./datahub-data-adaptation.html">Data Adaptation</a> — Transform and adapt values inside a child map</li><li><a href="./build-data-models.html">Data Models</a> — Defining child models and Entity Sub Types</li><li><a href="./datahub-code-view.html">Code View</a> — View the underlying map-group configuration</li></ul>`,40)])])}const k=t(n,[["render",o]]);export{g as __pageData,k as default};
